{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
const nameRe = /^[A-Za-z0-9_-]+$/
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  if (w[0] === 'candidates') {
    if (cands !== null || ballots.length) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const c of w.slice(1)) {
      if (!nameRe.test(c)) fail(`error: line ${n}: invalid candidate name ${c}`)
      if (seen.has(c)) fail(`error: line ${n}: candidate ${c} is declared twice`)
      seen.add(c)
    }
    cands = w.slice(1)
  } else if (w[0] === 'ballot') {
    if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(w[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const c of w.slice(2)) {
      if (!cands.includes(c)) fail(`error: line ${n}: unknown candidate ${c}`)
      if (seen.has(c)) fail(`error: line ${n}: candidate ${c} is repeated`)
      seen.add(c)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

const cont = new Set(cands)
const hist = new Map(cands.map(c => [c, []]))
const out = []
let roundNo = 0
let result = 'no winner'
for (;;) {
  roundNo++
  const cnt = new Map([...cont].map(c => [c, 0n]))
  let total = 0n
  let exhausted = 0n
  for (const b of ballots) {
    const c = b.prefs.find(p => cont.has(p))
    if (c === undefined) exhausted += b.count
    else { cnt.set(c, cnt.get(c) + b.count); total += b.count }
  }
  for (const [c, v] of cnt) hist.get(c).push(v)
  const order = [...cnt.keys()].sort((a, b) => (cnt.get(a) > cnt.get(b) ? -1 : cnt.get(a) < cnt.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
  let line = `round ${roundNo}: ` + order.map(c => `${c}=${cnt.get(c)}`).join(' ') + ` exhausted=${exhausted}`
  out.push(line)
  if (total === 0n) break
  const win = order.find(c => cnt.get(c) * 2n > total)
  if (win !== undefined) { result = `winner ${win}`; break }
  let min = null
  for (const v of cnt.values()) if (min === null || v < min) min = v
  let set = order.filter(c => cnt.get(c) === min)
  while (set.length > 1) {
    let k = 0
    for (; k < roundNo; k++) {
      const vs = set.map(c => hist.get(c)[k])
      if (vs.some(v => v !== vs[0])) {
        const m = vs.reduce((a, b) => (b < a ? b : a))
        set = set.filter(c => hist.get(c)[k] === m)
        break
      }
    }
    if (k === roundNo) {
      set = [set.reduce((a, b) => (b > a ? b : a))]
    }
  }
  out.push(`eliminated ${set[0]}`)
  cont.delete(set[0])
}
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + result + '\n')
else process.stdout.write(`rounds ${roundNo}\n${result}\n`)
EOF
node --test test/*.test.js 2>&1 | grep -E "^# (pass|fail)"","description":"Write cli.js and run tests"}

