{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'tokens' && mode[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

class ScanError extends Error {
  constructor(line, col, reason) { super(reason); this.line = line; this.col = col }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  let i = 0, line = 1, col = 1
  const tokens = []
  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const err = (l, c, r) => { throw new ScanError(l, c, r) }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const tl = line, tc = col
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) err(tl, tc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let v = ''
      for (;;) {
        if (i >= n) err(tl, tc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        v += d
      }
      tokens.push([tl, tc, 'rawstring', JSON.stringify(v)])
      continue
    }
    if (isIdStart(c)) {
      let s = ''
      while (i < n && isIdChar(cs[i])) s += adv()
      tokens.push([tl, tc, KEYWORDS.has(s) ? 'keyword' : 'ident', s])
      continue
    }
    if (isDigit(c)) {
      let s = ''
      const take = () => { s += adv() }
      const run = (ok) => {
        // at least one digit assumed present at cs[i]; underscores only between digits
        take()
        for (;;) {
          if (ok(cs[i])) take()
          else if (cs[i] === '_' && ok(cs[i + 1])) { take(); take() }
          else break
        }
      }
      let bad = false
      const p = cs[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        take(); take()
        const ok = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? (x) => x === '0' || x === '1' : (x) => x !== undefined && x >= '0' && x <= '7'
        if (ok(cs[i])) run(ok)
        else bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { take(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) { take(); run(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { take(); take(); run(isDigit) }
        }
      }
      if (bad || (i < n && isIdChar(cs[i]))) {
        while (i < n && isIdChar(cs[i])) take()
        err(tl, tc, `invalid number ${s}`)
      }
      tokens.push([tl, tc, 'number', s])
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) err(tl, tc, 'unterminated string')
        const el = line, ec = col
        const d = adv()
        if (d === '"') break
        if (d === '\n') err(el, ec, 'newline in string')
        if (d !== '\\') { v += d; continue }
        if (i >= n) err(tl, tc, 'unterminated string')
        const e = adv()
        const bad = () => err(el, ec, `invalid escape \\${e}`)
        if (e === 'n') v += '\n'
        else if (e === 't') v += '\t'
        else if (e === 'r') v += '\r'
        else if (e === '\\') v += '\\'
        else if (e === '"') v += '"'
        else if (e === '0') v += '\0'
        else if (e === 'x') {
          if (!isHex(cs[i]) || !isHex(cs[i + 1])) bad()
          v += String.fromCharCode(parseInt(cs[i] + cs[i + 1], 16)); adv(); adv()
        } else if (e === 'u') {
          if (cs[i] !== '{') bad()
          let j = i + 1, h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}') bad()
          const t = h.replace(/^0+/, '')
          if (t.length > 6 || parseInt(t || '0', 16) > 0x10ffff) bad()
          v += String.fromCodePoint(parseInt(h, 16))
          while (i <= j) adv()
        } else bad()
      }
      tokens.push([tl, tc, 'string', JSON.stringify(v)])
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    const pu = PUNCT.find((q) => (q.length === 2 ? q === two : q === c))
    if (pu) {
      for (let k = 0; k < pu.length; k++) adv()
      tokens.push([tl, tc, 'punct', pu])
      continue
    }
    err(tl, tc, `unexpected character ${c}`)
  }
  return tokens
}

let out
try {
  const tokens = scan(readFileSync(0, 'utf8'))
  if (mode[0] === 'tokens') out = tokens.map((t) => `${t[0]}:${t[1]} ${t[2]} ${t[3]}\n`).join('')
  else {
    const counts = {}
    for (const t of tokens) counts[t[2]] = (counts[t[2]] || 0) + 1
    out = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string'].map((k) => `${k} ${counts[k] || 0}\n`).join('') + `total ${tokens.length}\n`
  }
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
EOF
