/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { readFileSync } from 'node:fs'
import { parseElection } from './parse.js'
import { count } from './count.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
  fail('error: usage: cli.js rounds|tally')
}

let election
try {
  election = parseElection(readFileSync(0, 'utf8'))
} catch (e) {
  if (e && e.isParseError) fail(e.message)
  throw e
}

const result = count(election)
let out = ''
if (args[0] === 'rounds') {
  result.rounds.forEach((r, i) => {
    out += `round ${i + 1}: ${r.lines.map(([n, v]) => `${n}=${v}`).join(' ')} exhausted=${r.exhausted}\n`
    if (r.eliminated !== null) out += `eliminated ${r.eliminated}\n`
  })
} else {
  out += `rounds ${result.rounds.length}\n`
}
out += result.winner === null ? 'no winner\n' : `winner ${result.winner}\n`
process.stdout.write(out)
"}

{"file_path":"src/parse.js","content":"function perr(msg) {
  const e = new Error(msg)
  e.isParseError = true
  return e
}

const NAME = /^[A-Za-z0-9_-]+$/

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const word = t[0]
    if (word === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        throw perr(`error: line ${n}: candidates must be declared once, before any ballot`)
      }
      if (t.length < 2) throw perr(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) throw perr(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) throw perr(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (word === 'ballot') {
      if (candidates === null) {
        throw perr(`error: line ${n}: candidates must be declared once, before any ballot`)
      }
      if (t.length < 3) throw perr(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) throw perr(`error: line ${n}: count must be a positive integer`)
      const known = new Set(candidates)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!known.has(name)) throw perr(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) throw perr(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      throw perr(`error: line ${n}: unknown directive ${word}`)
    }
  }
  if (candidates === null) throw perr('error: no candidates')
  return { candidates, ballots }
}
"}

{"file_path":"src/count.js","content":"export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const pick = b.prefs.find((p) => continuing.has(p))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    for (const [c, v] of votes) history.get(c).push(v)
    const lines = [...votes].sort((a, b) =>
      a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0,
    ).map(([c, v]) => [c, v.toString()])
    const round = { lines, exhausted: (total - active).toString(), eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [c, v] of votes) {
      if (v * 2n > active) return { rounds, winner: c }
    }
    let pool = [...continuing]
    for (let r = 0; r < rounds.length && pool.length > 1; r++) {
      let min = null
      for (const c of pool) {
        const v = history.get(c)[r]
        if (min === null || v < min) min = v
      }
      pool = pool.filter((c) => history.get(c)[r] === min)
    }
    pool.sort()
    const out = pool[pool.length - 1]
    continuing.delete(out)
    round.eliminated = out
  }
}
"}

