      let j = i + 2
      while (j < n && depth > 0) {
        if (cs[j] === '/' && cs[j + 1] === '*') {
          depth++
          j += 2
        } else if (cs[j] === '*' && cs[j + 1] === '/') {
          depth--
          j += 2
        } else j++
