import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const ID = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function int(v, field, least) {
  if (!INT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(v)
}

function run(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const stats = new Map()
  const out = []
  let started = false
  let lastTick = null
  let allowed = 0, denied = 0
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const w = line.split(/\s+/)
    const at = (m) => new Fail(m)
    try {
      const d = w[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (started) throw at('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (w.length !== 5) throw at('expected bucket <name> <capacity> <refill> <per>')
        if (!ID.test(w[1])) throw at(`invalid policy name ${w[1]}`)
        const capacity = int(w[2], 'capacity', 1)
        const refill = int(w[3], 'refill', 0)
        const per = int(w[4], 'per', 1)
        if (policies.has(w[1])) throw at(`policy ${w[1]} is declared twice`)
        policies.set(w[1], { name: w[1], kind: 'bucket', capacity, refill, per, st: new Map() })
      } else if (d === 'window') {
        if (w.length !== 4) throw at('expected window <name> <limit> <span>')
        if (!ID.test(w[1])) throw at(`invalid policy name ${w[1]}`)
        const limit = int(w[2], 'limit', 0)
        const span = int(w[3], 'span', 1)
        if (policies.has(w[1])) throw at(`policy ${w[1]} is declared twice`)
        policies.set(w[1], { name: w[1], kind: 'window', limit, span, st: new Map() })
      } else if (d === 'route') {
        if (w.length < 3) throw at('expected route <prefix> <policy>...')
        if (!ID.test(w[1])) throw at(`invalid route prefix ${w[1]}`)
        if (routes.has(w[1])) throw at(`prefix ${w[1]} is routed twice`)
        const list = []
        for (const n of w.slice(2)) {
          if (!policies.has(n)) throw at(`unknown policy ${n}`)
          list.push(policies.get(n))
        }
        routes.set(w[1], list)
      } else if (d === 'event') {
        if (w.length !== 3) throw at('expected event <tick> <key>')
        const tick = int(w[1], 'tick', 0)
