{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

function sortedKeys(m) {
  return [...m.keys()].sort(cmp)
}

function ser(node, ind) {
  switch (node.t) {
    case 'table': {
      const ks = sortedKeys(node.m)
      if (!ks.length) return '{}'
      const pad = '  '.repeat(ind + 1)
      return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + ser(node.m.get(k), ind + 1)).join(',\n') + '\n' + '  '.repeat(ind) + '}'
    }
    case 'array': {
      if (!node.items.length) return '[]'
      const pad = '  '.repeat(ind + 1)
      return '[\n' + node.items.map((n) => pad + ser(n, ind + 1)).join(',\n') + '\n' + '  '.repeat(ind) + ']'
    }
    case 'integer':
      return node.v.toString()
    default:
      return JSON.stringify(node.v)
  }
}

export function toJson(root) {
  return ser(root, 0) + '\n'
}

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node.m)) visit(node.m.get(k), path === null ? k : path + '.' + k)
    } else if (node.t === 'array') {
      node.items.forEach((n, i) => visit(n, path + '[' + i + ']'))
    }
  }
  const visit = (node, path) => {
    lines.push(path + ' ' + node.t)
    walk(node, path)
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
"}

