export class UriError extends Error {}

export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  const [, scheme, authority, path, query, fragment] = m
  return { scheme, authority, path, query, fragment }
}

export function removeDots(path) {
  let input = path
  const out = []
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out.pop()
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out.push(seg)
      input = input.slice(seg.length)
    }
  }
  return out.join('')
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s, name) {
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new UriError(`the ${name} has a truncated percent-encoding`)
}
function normPct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}
const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at < 0 ? undefined : a.slice(0, at)
  const rest = a.slice(at + 1)
  const c = rest.indexOf(':', rest.lastIndexOf(']') + 1)
  return c < 0 ? { userinfo, host: rest, port: undefined } : { userinfo, host: rest.slice(0, c), port: rest.slice(c + 1) }
}

export function normalize(u) {
  let { scheme, authority, path, query, fragment } = u
  let au
  if (authority !== undefined) au = splitAuthority(authority)
  pct(path, 'path')
  if (au) { if (au.userinfo !== undefined) pct(au.userinfo, 'userinfo'); pct(au.host, 'host') }
  if (query !== undefined) pct(query, 'query')
  if (fragment !== undefined) pct(fragment, 'fragment')
  if (scheme !== undefined) scheme = lower(scheme)
  let out = scheme !== undefined ? scheme + ':' : ''
  if (au) {
    let port = au.port
    if (port === '' || (port !== undefined && port === DEFAULT_PORT[scheme])) port = undefined
    out += '//'
    if (au.userinfo !== undefined) out += normPct(au.userinfo) + '@'
    out += lower(normPct(au.host))
    if (port !== undefined) out += ':' + port
  }
  path = removeDots(normPct(path))
  if (au && path === '') path = '/'
  out += path
  if (query !== undefined) out += '?' + normPct(query)
  if (fragment !== undefined) out += '#' + normPct(fragment)
  return out
}

export function resolve(base, ref) {
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  if (ref.authority !== undefined) return { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  const t = { scheme: base.scheme, authority: base.authority, fragment: ref.fragment }
  if (ref.path === '') {
    t.path = base.path
    t.query = ref.query !== undefined ? ref.query : base.query
  } else {
    t.query = ref.query
    if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
    else {
      let merged
      if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
      else merged = base.path.slice(0, base.path.lastIndexOf('/') + 1) + ref.path
      t.path = removeDots(merged)
    }
  }
  return t
}
