#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */
import { readFileSync } from 'node:fs'
import { parse, normalize, resolve, UriError } from './uri.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) fail('error: usage: cli.js normalize|resolve')
const mode = args[0]
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const results = []
lines.forEach((line, i) => {
  try {
    if (mode === 'normalize') results.push(normalize(parse(line)))
    else {
      const sp = line.indexOf(' ')
      if (sp < 0) throw new UriError('expected a base and a reference')
      const base = parse(line.slice(0, sp))
      if (base.scheme === undefined) throw new UriError('the base has no scheme')
      results.push(normalize(resolve(base, parse(line.slice(sp + 1)))))
    }
  } catch (e) {
    if (e instanceof UriError) fail(`error: line ${i + 1}: ${e.message}`)
    throw e
  }
})
