import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

const args = process.argv.slice(2)
let workers = 0
if (args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) {
  // ok
} else if (args.length === 2 && args[0] === 'pack') {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail('error: usage: cli.js waves|explain|pack <workers>')
const mode = args[0]

let text = ''
try { text = readFileSync(0, 'utf8') } catch { text = '' }
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depUses = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) depUses.push(x)
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const x of depUses) if (!cost.has(x)) fail(`error: unknown task ${x}`)

const names = [...cost.keys()].sort(cmp)
const dl = new Map(names.map((k) => [k, [...(deps.get(k) || [])].sort(cmp)]))

// cycle detection
const state = new Map()
const stack = []
function dfs(u) {
  state.set(u, 1)
  stack.push(u)
  for (const v of dl.get(u)) {
    if (state.get(v) === 1) {
      const c = stack.slice(stack.indexOf(v))
      c.push(v)
      fail('error: cycle: ' + c.join(' -> '), 3)
    }
    if (!state.has(v)) dfs(v)
  }
  stack.pop()
  state.set(u, 2)
}
for (const k of names) if (!state.has(k)) dfs(k)

// topological order via memoized recursion (graph is acyclic)
const start = new Map(), finish = new Map(), depth = new Map(), prio = new Map()
function calc(u) {
  if (finish.has(u)) return
  let s = 0, d = 0
  for (const v of dl.get(u)) {
    calc(v)
    s = Math.max(s, finish.get(v))
    d = Math.max(d, depth.get(v) + 1)
  }
  start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
}
names.forEach(calc)
const total = names.reduce((m, k) => Math.max(m, finish.get(k)), 0)
const rev = new Map(names.map((k) => [k, []]))
for (const k of names) for (const v of dl.get(k)) rev.get(v).push(k)
function pr(u) {
  if (prio.has(u)) return prio.get(u)
  let m = 0
  for (const x of rev.get(u)) m = Math.max(m, pr(x))
  prio.set(u, m + cost.get(u))
  return m + cost.get(u)
}
names.forEach(pr)

const out = []
if (mode === 'waves') {
  const waves = []
  for (const k of names) (waves[depth.get(k)] ||= []).push(k)
  waves.forEach((w, i) => out.push(`wave ${i}: ${w.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const k of names) out.push(`${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}`)
  out.push(`total ${total}`)
} else {
  const free = new Array(workers).fill(0)
  const ran = Array.from({ length: workers }, () => [])
  const fin = new Map()
  let left = names.length
  let t = 0
  let makespan = 0
  while (left > 0) {
    for (;;) {
      const wi = free.findIndex((f) => f <= t)
      if (wi < 0) break
      let best = null
      for (const k of names) {
        if (fin.has(k)) continue
        if (!dl.get(k).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null || prio.get(k) > prio.get(best)) best = k
      }
      if (best === null) break
      const f = t + cost.get(best)
      fin.set(best, f)
      free[wi] = f
      ran[wi].push(`${best}@${t}-${f}`)
      makespan = Math.max(makespan, f)
      left--
    }
    if (left === 0) break
    let next = Infinity
    for (const f of fin.values()) if (f > t && f < next) next = f
    t = next
  }
  ran.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
EOF
