import { parseAddr, addrKey } from './sheet.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (code) => ({ t: 'err', v: code })
const num = (v) => ({ t: 'num', v })

// ---- parser ----
class Bad extends Error {}

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: parseFloat(m[0]) }); i += m[0].length
      if (/[0-9.]/.test(s[i] ?? '') ) throw new Bad()
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length
    } else throw new Bad()
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].k === 'op' && toks[p].v === v
  const CMP = ['=', '<>', '<', '<=', '>', '>=']
  function cmp() {
    let l = add()
    while (peek() && peek().k === 'op' && CMP.includes(peek().v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw new Bad()
    if (t.k === 'num') { p++; return { n: 'num', v: t.v } }
    if (isOp('(')) {
      p++
      const e = cmp()
      if (!isOp(')')) throw new Bad()
      p++
      return e
    }
    if (t.k === 'word') {
      p++
      const name = t.v.toUpperCase()
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(arg())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            throw new Bad()
          }
        }
        return { n: 'call', name, args }
      }
      if (isOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.k !== 'word') throw new Bad()
        p++
        if (isOp('(')) throw new Bad()
        return { n: 'range', a: t.v.toUpperCase(), b: t2.v.toUpperCase() }
      }
      if (name === 'TRUE') return { n: 'bool', v: true }
      if (name === 'FALSE') return { n: 'bool', v: false }
      return { n: 'ref', a: name }
    }
    throw new Bad()
  }
  function arg() {
    // a range directly as an argument is allowed; otherwise a full expression
    const e = cmp()
    return e
  }
  const e = cmp()
  if (p !== toks.length) throw new Bad()
  return e
}

const RANGE_FUNCS = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
// true if a range sits where it is not allowed
function misplaced(node, direct = false) {
  switch (node.n) {
    case 'range': return !direct
    case 'bin': return misplaced(node.l) || misplaced(node.r)
    case 'un': return misplaced(node.e)
    case 'call': {
      const ok = !['ABS', 'IF'].includes(node.name)
      return node.args.some((a) => misplaced(a, ok))
    }
    default: return false
  }
}

function rangeCells(node) {
  const a = parseAddr(node.a), b = parseAddr(node.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(addrKey(c, r))
  return out
}

function collect(node, set) {
  switch (node.n) {
    case 'ref': { const a = parseAddr(node.a); if (a) set.add(addrKey(a.col, a.row)); break }
    case 'range': { const cs = rangeCells(node); if (cs) cs.forEach((k) => set.add(k)); break }
    case 'bin': collect(node.l, set); collect(node.r, set); break
    case 'un': collect(node.e, set); break
    case 'call': node.args.forEach((a) => collect(a, set)); break
  }
}

function literal(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(parseFloat(content))
  if (ERRORS.includes(content)) return err(content)
  return { t: 'text', v: content }
}

function prepare(cell) {
  if (cell.content[0] !== '=') return { lit: literal(cell.content) }
  try {
    const ast = parseFormula(cell.content.slice(1))
    return { ast, bad: misplaced(ast) }
  } catch (e) {
    if (e instanceof Bad) return { bad: true }
    throw e
  }
}

const cmpRank = { num: 0, text: 1, bool: 2 }
function compare(l, r) {
  if (l.t !== r.t) return cmpRank[l.t] - cmpRank[r.t]
  if (l.t === 'text') {
    const a = [...l.v], b = [...r.v]
    for (let i = 0; i < Math.min(a.length, b.length); i++) {
      const d = a[i].codePointAt(0) - b[i].codePointAt(0)
      if (d) return d
    }
    return a.length - b.length
  }
  return Number(l.v) - Number(r.v)
}

function makeEvaluator(cells) {
  const prepared = new Map()
  for (const c of cells) prepared.set(c.key, prepare(c))
  const memo = new Map()
  const visiting = new Set()

  function cellValue(key) {
    if (!prepared.has(key)) return num(0)
    if (memo.has(key)) return memo.get(key)
    if (visiting.has(key)) return err('#CYCLE!')
    visiting.add(key)
    const pr = prepared.get(key)
    let v
    if (pr.lit) v = pr.lit
    else if (pr.bad) v = err('#ERR!')
    else v = ev(pr.ast)
    visiting.delete(key)
    memo.set(key, v)
    return v
  }

  const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
  function toNum(v) {
    if (v.t === 'num') return v
    if (v.t === 'bool') return num(v.v ? 1 : 0)
    if (v.t === 'text') return err('#VALUE!')
    return v
  }

  function ev(n) {
    switch (n.n) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'bool', v: n.v }
      case 'ref': {
        const a = parseAddr(n.a)
        return a ? cellValue(addrKey(a.col, a.row)) : err('#REF!')
      }
      case 'range': return err('#ERR!')
      case 'un': {
        const x = toNum(ev(n.e))
        if (x.t === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': {
        const lv = ev(n.l)
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          if (lv.t === 'err') return lv
          const rv = ev(n.r)
          if (rv.t === 'err') return rv
          const d = compare(lv, rv)
          const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
          return { t: 'bool', v: res }
        }
        const l = toNum(lv)
        if (l.t === 'err') return l
        const r = toNum(ev(n.r))
        if (r.t === 'err') return r
        switch (n.op) {
          case '+': return finite(l.v + r.v)
          case '-': return finite(l.v - r.v)
          case '*': return finite(l.v * r.v)
          case '/': return r.v === 0 ? err('#DIV/0!') : finite(l.v / r.v)
          case '^': return finite(Math.pow(l.v, r.v))
        }
        return err('#ERR!')
      }
      case 'call': return call(n)
    }
    return err('#ERR!')
  }

  function call(n) {
    const name = n.name
    const known = RANGE_FUNCS.includes(name) || name === 'ABS' || name === 'IF'
    if (!known) return err('#NAME?')
    if (name === 'ABS' && n.args.length !== 1) return err('#ERR!')
    if (name === 'IF' && n.args.length !== 3) return err('#ERR!')
    if (RANGE_FUNCS.includes(name) && n.args.length < 1) return err('#ERR!')
    if (name === 'IF') {
      const c = ev(n.args[0])
      if (c.t === 'err') return c
      if (c.t === 'text') return err('#VALUE!')
      const truth = c.t === 'bool' ? c.v : c.v !== 0
      return ev(n.args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      const x = toNum(ev(n.args[0]))
      return x.t === 'err' ? x : num(Math.abs(x.v))
    }
    const vals = []
    for (const a of n.args) {
      if (a.n === 'range') {
        const cs = rangeCells(a)
        if (!cs) vals.push(err('#REF!'))
        else for (const k of cs) vals.push(cellValue(k))
      } else vals.push(ev(a))
    }
    const firstErr = vals.find((v) => v.t === 'err')
    if (firstErr) return firstErr
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'err') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'SUM': return finite(nums.reduce((a, b) => a + b, 0))
      case 'MIN': return num(Math.min(...nums))
      case 'MAX': return num(Math.max(...nums))
      case 'AVG': return finite(nums.reduce((a, b) => a + b, 0) / nums.length)
    }
    return err('#ERR!')
  }

  return { cellValue, prepared }
}

function show(v) {
  switch (v.t) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

export function evaluateAll(cells) {
  const { cellValue } = makeEvaluator(cells)
  return cells.map((c) => `${c.key}=${show(cellValue(c.key))}\n`).join('')
}

export function depsAll(cells) {
  let out = ''
  for (const c of cells) {
    const set = new Set()
    if (c.content[0] === '=') {
      try { collect(parseFormula(c.content.slice(1)), set) } catch (e) { if (!(e instanceof Bad)) throw e }
    }
    const list = [...set].map((k) => parseAddr(k) && { k, ...parseAddr(k) })
      .sort((x, y) => x.col - y.col || x.row - y.row)
    out += `${c.key}:${list.map((x) => ' ' + x.k).join('')}\n`
  }
  return out
}
EOF
