import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let last = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    const fail = (m) => { throw new Fail(`line ${i + 1}: ${m}`) }
    const num = (v, field, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = f[0]
    if (d === 'bucket' || d === 'window' || d === 'route') {
      const want = d === 'bucket' ? 5 : d === 'window' ? 4 : null
      if (d === 'bucket' && f.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
      if (d === 'window' && f.length !== 4) fail('expected window <name> <limit> <span>')
      if (d === 'route' && f.length < 3) fail('expected route <prefix> <policy>...')
      void want
      if (started) fail('declarations must come before the first event')
      if (d === 'route') {
        if (!NAME.test(f[1])) fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) fail(`prefix ${f[1]} is routed twice`)
        const ps = f.slice(2).map((n) => {
          if (!policies.has(n)) fail(`unknown policy ${n}`)
          return policies.get(n)
        })
        routes.set(f[1], ps)
      } else {
        if (!NAME.test(f[1])) fail(`invalid policy name ${f[1]}`)
        let p
        if (d === 'bucket') {
          const capacity = num(f[2], 'capacity', 1)
          const refill = num(f[3], 'refill', 0)
          const per = num(f[4], 'per', 1)
          p = { name: f[1], kind: 'b', capacity, refill, per }
        } else {
          const limit = num(f[2], 'limit', 0)
          const span = num(f[3], 'span', 1)
          p = { name: f[1], kind: 'w', limit, span }
        }
        if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], p)
      }
    } else if (d === 'event') {
      if (f.length !== 3) fail('expected event <tick> <key>')
      const tick = num(f[1], 'tick', 0)
      if (!NAME.test(f[2])) fail(`invalid key ${f[2]}`)
      if (last !== null && tick < last) fail(`tick ${tick} is before tick ${last}`)
      last = tick
      started = true
      events.push([tick, f[2]])
    } else fail(`unknown directive ${d}`)
  }
  return { routes, events }
}

function run({ routes, events }) {
  const prefixes = [...routes.keys()].sort((a, b) => b.length - a.length)
  const states = new Map() // policy -> Map(key -> state)
  const stateOf = (p, key, tick) => {
    let m = states.get(p)
    if (!m) states.set(p, (m = new Map()))
    let s = m.get(key)
    if (!s) {
      s = p.kind === 'b' ? { units: p.capacity * p.per, at: tick } : { ticks: [] }
      m.set(key, s)
    }
    return s
  }
  const out = []
  for (const [tick, key] of events) {
    const pre = prefixes.find((x) => key.startsWith(x))
    if (pre === undefined) { out.push({ tick, key, by: null }); continue }
    const ps = routes.get(pre)
    const ss = ps.map((p) => {
      const s = stateOf(p, key, tick)
      if (p.kind === 'b') {
        const cap = p.capacity * p.per
        s.units += p.refill * (tick - s.at)
        if (s.units > cap) s.units = cap
        s.at = tick
      } else {
        const cut = tick - p.span
        s.ticks = s.ticks.filter((t) => t > cut)
      }
      return s
    })
    let by = null
    for (let i = 0; i < ps.length && by === null; i++) {
      const p = ps[i]
      const ok = p.kind === 'b' ? ss[i].units >= p.per : BigInt(ss[i].ticks.length) < p.limit
      if (!ok) by = p.name
    }
    if (by === null) {
      ps.forEach((p, i) => {
        if (p.kind === 'b') ss[i].units -= p.per
        else ss[i].ticks.push(tick)
      })
    }
    out.push({ tick, key, by })
  }
  return out
}

let text = ''
try {
  const data = run(parse(readFileSync(0, 'utf8')))
  let o = ''
  if (mode === 'replay') {
    for (const e of data) o += `${e.tick} ${e.key} ${e.by === null ? 'allow' : 'deny ' + e.by}\n`
  } else {
    const per = new Map()
    let a = 0, d = 0
    for (const e of data) {
      const c = per.get(e.key) || [0, 0]
      if (e.by === null) { c[0]++; a++ } else { c[1]++; d++ }
      per.set(e.key, c)
    }
    for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      o += `${k} allowed=${per.get(k)[0]} denied=${per.get(k)[1]}\n`
    }
    o += `total allowed=${a} denied=${d}\n`
  }
  text = o
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(text)
